import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int[] a = new int[3];
        int[] b = new int[3];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < 3; i++) a[i] = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < 3; i++) b[i] = Integer.parseInt(st.nextToken());
        int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int min = Integer.MAX_VALUE;
        List<int[]> pairs = new ArrayList<>();
        pairs.add(new int[]{0, 0});
        pairs.add(new int[]{1, 1});
        pairs.add(new int[]{2, 2});
        pairs.add(new int[]{0, 2});
        pairs.add(new int[]{1, 0});
        pairs.add(new int[]{2, 1});
        min = findMin(pairs, 0, a, b, min);
        pw.println(min + " " + max);
        pw.close();
    }

    static int findMin(List<int[]> pairs, int index, int[] a, int[] b, int min) {
        int[] aCopy = a.clone();
        int[] bCopy = b.clone();
        for (int[] pair : pairs) {
            int m = Math.min(aCopy[pair[0]], bCopy[pair[1]]);
            bCopy[pair[1]] -= m;
            aCopy[pair[0]] -= m;
        }
        int curr = 0;
        for (int i = 0; i < 3; i++) curr += aCopy[i];
        min = Math.min(min, curr);
        for (int i = index; i < pairs.size(); i++) {
            Collections.swap(pairs, i, index);
            min = findMin(pairs, index + 1, a, b, min);
            Collections.swap(pairs, i, index);
        }
        return min;
    }
}
